INSERT INTO item VALUES (103,'Wyrm, Red','Rod','Epic','No',NULL,'34','1,897,400 gp',NULL,'Craft Rod, Craft Epic Rod, Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, Improved Heighten Spell, improved heightened polymorph, creator must be same alignment as dragon type','949,000 gp + 28,968 XP',NULL,'\n      <div topic=\"Wyrm\" level=\"8\"><p><b>Wyrm:</b> Any of the various rods in this series functions as a +<i>5 quarterstaff</i>. Upon casting the rod to the ground (a standard action) and uttering a command word, the rod grows into a specific type of dragon (depending on the specific type of rod) by the end of the round. The dragon created is a wyrm and obeys the commands of the owner. The dragon returns to rod form (a full-round action) whenever the wielder desires, or whenever it moves farther than 500 feet from the owner. If the dragon form is slain, it returns to rod form and cannot be activated again for three days. A <i>wyrm rod</i> only functions if the possessor is of the same alignment as the dragon type.</p><p><i>Caster Level:</i> 34th (white or brass), 35th (black or copper), 36th (green or bronze), 37th (blue or silver), 38th (red or gold); <i>Prerequisites:</i> Craft Rod, Craft Epic Rod, Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, Improved Heighten Spell, improved heightened <i>polymorph</i>,  creator must be same alignment as dragon type; <i>Market Price:</i> 1,458,200 gp (brass or white), 1,562,600 gp (black or copper), 1,670,600 gp (bronze or green), 1,782,200 gp (blue or silver), 1,897,400 gp (gold or red); <i>Cost to Create:</i> 729,400 gp + 24,576 XP (brass or white), 781,600 gp + 25,620 XP (black or copper), 835,600 gp + 26,700 XP (bronze or green), 891,400 gp + 27,816 XP (blue or silver), 949,000 gp + 28,968 XP (gold or red).</p><p/>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (104,'Cosmos','Staff','Epic','No',NULL,'27','683,437 gp',NULL,'Craft Staff, Craft Epic Staff, Intensify Spell, chain lightning, meteor swarm, sunburst',NULL,NULL,'\n      <div topic=\"Cosmos\" level=\"8\"><p><b>Cosmos:</b>  This staff allows use of the following spells.</p><ul>\n <li> <i>Chain lightning</i> (intensified, 1 charge, DC 29)</li>\n <li> <i>Meteor swarm</i> (intensified, 1 charge, DC 34)</li>\n <li> <i>Sunburst</i> (intensified, 1 charge, DC 32)</li>\n</ul><p><i>Caster Level:</i> 27th; <i>Prerequisites:</i> Craft Staff, Craft Epic Staff, Intensify Spell, <i>chain lightning</i>,  <i>meteor swarm</i>,  <i>sunburst; Market Price:</i> 683,437 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (105,'Domination','Staff','Epic','No',NULL,'21','464,400 gp',NULL,'Craft Staff, Craft Epic Staff, Heighten Spell, demand, dominate monster, geas, mass charm monster',NULL,NULL,'\n      <div topic=\"Domination\" level=\"8\"><p><b>Domination:</b> This staff allows use of the following heightened spells.</p><ul>\n <li> <i>Dominate monster</i> (1 charge, DC 33)</li>\n <li> <i>Demand</i> (1 charge, DC 32)</li>\n <li> <i>Mass charm monster</i> (1 charge, DC 32)</li>\n <li> <i>Geas</i> (heightened, 1 charge, DC 33)</li>\n</ul><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Staff, Craft Epic Staff, Heighten Spell, <i>demand</i>,  <i>dominate monster</i>,  <i>geas</i>,  <i>mass charm monster; Market Price:</i> 464,400 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (106,'Fiery Power','Staff','Epic','No',NULL,'25','500,000 gp',NULL,'Craft Staff, Craft Epic Staff, Extend Spell, Heighten Spell, Improved Heighten Spell, Intensify Spell, Spell Focus (Evocation), continual flame, delayed blast fireball, meteor swarm, protection from energy, summon monster IX, wall of fire',NULL,NULL,'\n      <div topic=\"Fiery Power\" level=\"8\"><p><b>Fiery Power:</b> This +<i>5 flaming quarterstaff</i> grants its wielder fire resistance 30 whenever held. In addition, it has the following powers.</p><ul>\n <li> <i>Wall of fire</i> (extended, 1 charge, DC 18)</li>\n <li> <i>Delayed blast fireball</i> (intensified to 240 points of damage, 2 charges, DC 22)</li>\n <li> <i>Meteor swarm</i>(heightened to 12th, 2 charges, DC 30)</li>\n <li> <i>Summon monster IX</i> (extended, 2 charges, elder fire elemental only) A <i>staff of fiery power</i> can be broken in a retributive strike. The breaking of the staff must be purposeful and declared by the wielder. All charges currently in the staff are instantly released in a 30-foot- radius globe. All within 10 feet of the broken staff take points of damage equal to eight times the number of charges in the staff, those between 11 feet and 20 feet away take six times the number of charges in damage, and those 21 feet to 30 feet distant take four times the number of charges in damage. Successful Reflex saving throws (DC 17) reduce the damage sustained by half. The character breaking the staff has a 50% chance of traveling to another plane of existence; if he or she does not, the explosive release of spell energy destroys him or her. After all charges are used up from the staff, it remains a +<i>5 quarterstaff</i> with no special abilities. (Once empty of charges, it cannot be broken in a retributive strike.)</li>\n</ul><p><i>Caster Level:</i> 25th; <i>Prerequisites:</i> Craft Staff, Craft Epic Staff, Extend Spell, Heighten Spell, Improved Heighten Spell, Intensify Spell, Spell Focus (Evocation), <i>continual flame</i>,  <i>delayed blast fireball</i>,  <i>meteor swarm</i>,  <i>protection from energy</i>,  <i>summon monster IX</i>,  <i>wall of fire; Market Price:</i> 500,000 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (107,'The Hierophants','Staff','Epic','No',NULL,'27','501,187 gp',NULL,'Craft Staff, Craft Epic Staff, Enlarge Spell, Extend Spell, Intensify Spell, creeping doom, command plants, elemental swarm, shambler',NULL,NULL,'\n      <div topic=\"Hierophants\" level=\"8\"><p><b>The Hierophants:</b> This staff allows use of the following spells.</p><ul>\n <li> <i>Creeping doom</i> (enlarged, extended, 1 charge, DC 23)</li>\n <li> <i>Command plants</i> (enlarged, extended, 1 charge, DC 25)</li>\n <li> <i>Elemental swarm</i> (intensified, 2 charges, DC 34)</li>\n <li> <i>Shambler</i> (intensified, 2 charges, DC 34)</li>\n</ul><p><i>Caster Level:</i> 27th; <i>Prerequisites:</i> Craft Staff, Craft Epic Staff, Enlarge Spell, Extend Spell, Intensify Spell, <i>creeping doom</i>,  <i>command plants</i>,  <i>elemental swarm</i>,  <i>shambler; Market Price:</i> 501,187 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (108,'Mighty Force','Staff','Epic','No',NULL,'21','265,000 gp',NULL,'Craft Staff, Craft Epic Staff, Quicken Spell, crushing hand, forcecage, shield',NULL,NULL,'\n      <div topic=\"Mighty Force\" level=\"8\"><p><b>Mighty Force:</b> This staff has three powers.</p><ul>\n <li> <i>Shield</i> (quickened, 1 charge, may be activated once per round)</li>\n <li> <i>Forcecage</i> (1 charge)</li>\n <li> <i>Crushing hand</i> (1 charge)</li>\n</ul><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Staff, Craft Epic Staff, Quicken Spell, <i>crushing hand</i>,  <i>forcecage</i>,  <i>shield; Market Price:</i> 265,000 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (109,'Nature\'s Fury','Staff','Epic','No',NULL,'21','500,000 gp',NULL,'Craft Staff, Craft Epic Staff, Heighten Spell, Improved Heighten Spell, earthquake, fire storm, summon monster I (or summon nature\'s ally I), whirlwind',NULL,NULL,'\n      <div topic=\"Nature\'s Fury\" level=\"8\"><p><b>Nature\'s Fury:</b> This +<i>5 aberration bane quarterstaff</i> allows use of the following spells.</p><ul>\n <li> <i>earthquake</i> (1 charge)</li>\n <li> <i>Whirlwind</i> (heightened to 10th level, 1 charge, DC 25)</li>\n <li> <i>Fire storm</i> (heightened to 10th level, 1 charge, DC 25)</li>\n</ul><p>After all charges are used up from a <i>staff of nature\'s fury</i>,  it remains a +<i>5 quarterstaff</i> with no special abilities.</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Staff, Craft Epic Staff, Heighten Spell, Improved Heighten Spell, <i>earthquake</i>,  <i>fire storm</i>,  <i>summon monster I</i> (or <i>summon nature\'s ally</i> I), <i>whirlwind; Market Price:</i> 500,000 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (110,'Necromancy','Staff','Epic','No',NULL,'27','1,505,312 gp',NULL,'Craft Staff, Craft Epic Staff, Intensify Spell, Heighten Spell, Improved Heighten Spell, circle of death, create greater undead, finger of death, soul bind','1,290,156 gp + 14,303 XP',NULL,'\n      <div topic=\"Necromancy\" level=\"8\"><p><b>Necromancy:</b> This staff allows use of the following spells.</p><ul>\n <li> <i>Circle of death</i> (intensified, 2 charges, DC 29)</li>\n <li> <i>Create greater undead</i> (1 charge)</li>\n <li> <i>Finger of death</i> (improved heightened to 16th, 2 charges, DC 34)</li>\n <li> <i>Soul bind</i> (improved heightened to 16th, 2 charges, DC 34). The soul trapped through the use of the <i>soul bind</i> spell is trapped in the staff rather than a gem. Only by breaking the staff can the souls be freed.</li>\n</ul><p><i>Caster Level:</i> 27th; <i>Prerequisites:</i> Craft Staff, Craft Epic Staff, Intensify Spell, Heighten Spell, Improved Heighten Spell, <i>circle of death</i>,  <i>create greater undead</i>,  <i>finger of death</i>,  <i>soul bind; Market Price:</i> 1,505,312 gp; <i>Cost to Create:</i> 1,290,156 gp + 14,303 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (111,'Planar Might','Staff','Epic','No',NULL,'21','460,000 gp',NULL,'Craft Staff, Craft Epic Staff, gate, greater planar ally, greater planar binding, protection from energy',NULL,NULL,'\n      <div topic=\"Planar Might\" level=\"8\"><p><b>Planar Might:</b> The wielder of this powerful staff is immune to the effects of any planar alignment traits, as well as the positive-dominant and negative-dominant traits or a plane. It also allows use of the following spells.</p><ul>\n <li> <i>greater planar ally</i> (1 charge)</li>\n <li> <i>Greater planar binding</i> (1 charge)</li>\n <li> <i>Gate</i> (1 charge)</li>\n</ul><p>When using the <i>greater planar ally</i> power, the character must still bargain with the called creature.</p><p>In addition to its other powers, a <i>staff of planar might</i> is a +<i>5 outsider bane quarterstaff</i> (roll 1d4 to determine what alignment of outsiders the staff\'s bane power works against: 1=chaotic, 2=evil, 3=good, 4=lawful). After all charges are used up from a <i>staff of planar might</i>,  it remains a +<i>5 quarterstaff</i> with no special abilities.</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Staff, Craft Epic Staff, <i>gate</i>,  <i>greater planar ally</i>,  <i>greater planar binding</i>,  <i>protection from energy; Market Price:</i> 460,000 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (112,'Prism','Staff','Epic','No',NULL,'21','326,812 gp',NULL,'Craft Staff, Craft Epic Staff, Extend Spell, prismatic sphere, prismatic spray, prismatic wall',NULL,NULL,'\n      <div topic=\"Prism\" level=\"8\"><p><b>Prism:</b> This staff allows use of the following spells.</p><ul>\n <li> <i>Prismatic sphere</i> (extended, 1 charge, DC 25)</li>\n <li> <i>Prismatic spray</i> (extended, 1 charge, DC 22)</li>\n <li> <i>Prismatic wall</i> (extended, 1 charge, DC 23)</li>\n</ul><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Staff, Craft Epic Staff, Extend Spell, <i>prismatic sphere</i>,  <i>prismatic spray</i>,  <i>prismatic wall; Market Price:</i> 326,812 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (113,'Rapid Barrage','Staff','Epic','No',NULL,'25','417,750 gp',NULL,'Craft Staff, Craft Epic Staff, Enhance Spell, Heighten Spell, Intensify Spell, Quicken Spell, fireball, magic missile',NULL,NULL,'\n      <div topic=\"Rapid Barrage\" level=\"8\"><p><b>Rapid Barrage:</b> Either of the staff\'s two powers can be activated as a free action (though the staff may only be activated once per round).</p><ul>\n <li> <i>Magic missile</i> (intensified, quickened, 1 charge, 5 missiles dealing 10 points of damage each)</li>\n <li> <i>Fireball</i> (heightened to 6th, enhanced, quickened, 1 charge, 20d6 damage, DC 19)</li>\n</ul><p><i>Caster Level:</i> 25th; <i>Prerequisites:</i> Craft Staff, Craft Epic Staff, Enhance Spell, Heighten Spell, Intensify Spell, Quicken Spell, <i>fireball</i>,  <i>magic missile; Market Price:</i> 417,750 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (114,'Spheres','Staff','Epic','No',NULL,'21','228,375 gp',NULL,'Craft Staff, Craft Epic Staff, freezing sphere, resilient sphere, telekinetic sphere',NULL,NULL,'\n      <div topic=\"Spheres\" level=\"8\"><p><b>Spheres:</b> This staff allows use of the following spells.</p><ul>\n <li> <i>Freezing sphere</i> (1 charge, DC 19)</li>\n <li> <i>Resilient sphere</i> (1 charge, DC 16)</li>\n <li> <i>Telekinetic sphere</i> (1 charge, DC 22)</li>\n</ul><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Staff, Craft Epic Staff, <i>freezing sphere</i>,  <i>resilient sphere</i>,  <i>telekinetic sphere; Market Price:</i> 228,375 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (115,'Walls','Staff','Epic','No',NULL,'30','275,625 gp',NULL,'Craft Staff, Craft Epic Staff, Extend Spell, extended wall of force, wall of iron, wall of stone',NULL,NULL,'\n      <div topic=\"Walls\" level=\"8\"><p><b>Walls:</b> This staff allows use of the following spells.</p><ul>\n <li> <i>Wall of iron</i> (1 charge)</li>\n <li> <i>Wall of stone</i> (1 charge)</li>\n <li> <i>Wall of force</i> (1 charge)</li>\n</ul><p><i>Caster Level:</i> 30th; <i>Prerequisites:</i> Craft Staff, Craft Epic Staff, Extend Spell, extended <i>wall of force</i>,  <i>wall of iron</i>,  <i>wall of stone; Market Price:</i> 275,625 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (116,'Winter','Staff','Epic','No',NULL,'24','292,500 gp',NULL,'Craft Staff, Craft Epic Staff, Extend Spell, Intensify Spell, cone of cold, ice storm, freezing sphere, wall of ice',NULL,NULL,'\n      <div topic=\"Winter\" level=\"8\"><p><b>Winter:</b> This staff allows the use of the following spells.</p><ul>\n <li> <i>Cone of cold</i> (intensified, 2 charges, DC 28)</li>\n <li> <i>Ice storm</i> (intensified, 2 charges, DC 26)</li>\n <li> <i>Freezing sphere</i> (intensified, 2 charges, DC 29)</li>\n <li> <i>Wall of ice</i> (1 charge)</li>\n</ul><p><i>Caster Level:</i> 24th; <i>Prerequisites:</i> Craft Staff, Craft Epic Staff, Extend Spell, Intensify Spell, <i>cone of cold</i>,  <i>ice storm</i>,  <i>freezing sphere</i>,  <i>wall of ice; Market Price:</i> 292,500 gp.</p><p/>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (117,'Amulet of Epic Natural Armor +6','Wondrous','Epic','No',NULL,'20','720,000 gp',NULL,'Craft Wondrous Item, Craft Epic Wondrous Item, barkskin, creator\'s caster level must be three times the amulet\'s bonus',NULL,'-','\n      <div topic=\"Amulet of Epic Natural Armor\" level=\"8\"><p><b>Amulet of Epic Natural Armor:</b>  This amulet toughens the wearer\'s body and flesh, giving him or her an enhancement bonus to his or her natural armor of +6 or higher, depending on the type of amulet.</p><p><i>Caster Level:</i> 20th; <i>Prerequisites:</i> Craft Wondrous Item, Craft Epic Wondrous Item, <i>barkskin</i>,  creator\'s caster level must be three times the amulet\'s bonus; <i>Market Price:</i> 720,000 gp (+6), 980,000 gp (+7), 1,280,000 gp (+8), 1,620,000 gp (+9), 2,000,000 gp (+10); <i>Weight:</i> -.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
