INSERT INTO item VALUES (144,'Gate Key','Wondrous','Epic','No',NULL,'21','378,000 gp',NULL,'Craft Wondrous Item, Craft Epic Wondrous Item, gate',NULL,'1 lb','\n      <div topic=\"Gate Key\" level=\"8\"><p><b>Gate Key:</b> When properly operated, the gate key can be used to attune any bounded space, such as a doorway or a cave opening, to another bounded space on another plane of existence previously visited by the wielder. When two bounded spaces are attuned, an interdimensional portal springs up at each location, and the two portals are connected. When the wielder creates a pair of portals, he or she also establishes the necessary key that travelers must have to access the portal. Possible keys include nothing, a pearl, a particular hair color, or even the <i>Gate key</i> itself. Up to sixty different pairs of portals can be attuned in this manner. Once all sixty pairs of portals are created, the key cannot create additional gates, though it may still be the necessary key to access some or all of the portals. To any creature without the proper key, the interdimensional portals are not visible (through <i>True seeing</i> or similar magic reveals their presence).</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Wondrous Item, Craft Epic Wondrous Item, <i>gate; Market Price:</i> 378,000 gp; <i>Weight:</i> 1 lb.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (145,'Gloves of Epic Dexterity +8','Wondrous','Epic','No',NULL,'20','640,000 gp',NULL,'Craft Wondrous Item, Craft Epic Wondrous Item, cat\'s grace',NULL,'-','\n      <div topic=\"Gloves of Epic Dexterity\" level=\"8\"><p><b>Gloves of Epic Dexterity:</b> These gloves add an enhancement bonus of +8 or higher to the wearer\'s Dexterity score.</p><p><i>Caster Level:</i> 20th; <i>Prerequisites:</i> Craft Wondrous Item, Craft Epic Wondrous Item, <i>cat\'s grace; Market Price:</i> 640,000 gp (+8), 1,000,000 gp (+10), 1,440,000 gp (+12); <i>Weight:</i> -.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
