INSERT INTO item VALUES (148,'Headband of Epic Intellect +8','Wondrous','Epic','No',NULL,'20','640,000 gp',NULL,'Craft Wondrous Item, Craft Epic Wondrous Item, commune or legend lore',NULL,'-','\n      <div topic=\"Headband of Epic Intellect\" level=\"8\"><p><b>Headband of Epic Intellect:</b> This headband adds an enhancement bonus of +8 or higher to the wearer\'s Intelligence score.</p><p><i>Caster Level:</i> 20th; <i>Prerequisites:</i> Craft Wondrous Item, Craft Epic Wondrous Item, <i>commune</i> or <i>legend lore; Market Price:</i> 640,000 gp (+8), 1,000,000 gp (+10), 1,440,000 gp (+12); <i>Weight:</i> -.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (149,'Headband of Epic Intellect +10','Wondrous','Epic','No',NULL,'20','1,000,000 gp',NULL,'Craft Wondrous Item, Craft Epic Wondrous Item, commune or legend lore',NULL,'-','\n      <div topic=\"Headband of Epic Intellect\" level=\"8\"><p><b>Headband of Epic Intellect:</b> This headband adds an enhancement bonus of +8 or higher to the wearer\'s Intelligence score.</p><p><i>Caster Level:</i> 20th; <i>Prerequisites:</i> Craft Wondrous Item, Craft Epic Wondrous Item, <i>commune</i> or <i>legend lore; Market Price:</i> 640,000 gp (+8), 1,000,000 gp (+10), 1,440,000 gp (+12); <i>Weight:</i> -.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (150,'Headband of Epic Intellect +12','Wondrous','Epic','No',NULL,'20','1,440,000 gp',NULL,'Craft Wondrous Item, Craft Epic Wondrous Item, commune or legend lore',NULL,'-','\n      <div topic=\"Headband of Epic Intellect\" level=\"8\"><p><b>Headband of Epic Intellect:</b> This headband adds an enhancement bonus of +8 or higher to the wearer\'s Intelligence score.</p><p><i>Caster Level:</i> 20th; <i>Prerequisites:</i> Craft Wondrous Item, Craft Epic Wondrous Item, <i>commune</i> or <i>legend lore; Market Price:</i> 640,000 gp (+8), 1,000,000 gp (+10), 1,440,000 gp (+12); <i>Weight:</i> -.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (151,'Horseshoes of the Peerless Steed','Wondrous','Epic','No',NULL,'20','217,000 gp',NULL,'Craft Wondrous Item, Craft Epic Wondrous Item, Ride skill, haste, spell resistance',NULL,'1 lb. each','\n      <div topic=\"Horseshoes of the Peerless Steed\" level=\"8\"><p><b>Horseshoes of the Peerless Steed:</b> These horseshoes magically adhere to the feet of any hoofed creature. Anyone riding the creature gains a +10 competence bonus on Ride checks and is treated as having ranks in the appropriate Ride skill (and thus does not take the -5 penalty for riding an unfamiliar mount). The horseshoes grant the creature (or its rider, as appropriate) the effects of the Trample, Ride-by Attack, and Spirited Charge feats. The wearer of the horseshoes gains spell resistance 32 against enchantment effects. In addition, the ground speed of the creature wearing the horseshoes doubles.</p><p><i>Caster Level:</i> 20th; <i>Prerequisites:</i> Craft Wondrous Item, Craft Epic Wondrous Item, Ride skill, <i>haste</i>,  <i>spell resistance; Market Price:</i> 217,000 gp; <i>Weight:</i> 1 lb. each.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (152,'Mantle of Epic Spell Resistance','Wondrous','Epic','No',NULL,'29','290,000 gp',NULL,'Craft Wondrous Item, Craft Epic Wondrous Item, spell resistance',NULL,'1 lb','\n      <div topic=\"Mantle of Epic Spell Resistance\" level=\"8\"><p><b>Mantle of Epic Spell Resistance:</b> This garment is worn over normal clothing or armor. It grants the wearer spell resistance 40.</p><p><i>Caster Level:</i> 29th; <i>Prerequisites:</i> Craft Wondrous Item, Craft Epic Wondrous Item, <i>spell resistance; Market Price:</i> 290,000 gp; <i>Weight:</i> 1 lb.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (153,'Mantle of Great Stealth','Wondrous','Epic','No',NULL,'20','242,000 gp',NULL,'Craft Wondrous Item, Craft Epic Wondrous Item, blur, invisibility, nondetection, silence',NULL,'1 lb','\n      <div topic=\"Mantle of Great Stealth\" level=\"8\"><p><b>Mantle of Great Stealth:</b> The wearer of this cloak gains a +30 bonus on Hide and Move Silently checks. The wearer\'s outline is blurry and indistinct, granting concealment (20% miss chance) at all times (as the <i>blur</i> spell). The mantle also grants nondetection to its wearer (as the spell).</p><p><i>Caster Level:</i> 20th; <i>Prerequisites:</i> Craft Wondrous Item, Craft Epic Wondrous Item, <i>blur</i>,  <i>invisibility</i>,  <i>nondetection</i>,  <i>silence; Market Price:</i> 242,000 gp; <i>Weight:</i> 1 lb.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (154,'Periapt of Epic Wisdom +8','Wondrous','Epic','No',NULL,'20','640,000 gp',NULL,'Craft Wondrous Item, Craft Epic Wondrous Item, commune or legend lore',NULL,'-','\n      <div topic=\"Periapt of Epic Wisdom\" level=\"8\"><p><b>Periapt of Epic Wisdom:</b> This large pearl set on a chain grants an enhancement bonus of +8 or higher to the wearer\'s Wisdom score.</p><p><i>Caster Level:</i> 20th; <i>Prerequisites:</i> Craft Wondrous Item, Craft Epic Wondrous Item, <i>commune</i> or <i>legend lore; Market Price:</i> 640,000 gp (+8), 1,000,000 gp (+10), 1,440,000 gp (+12); <i>Weight:</i> -.</p><p/>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (155,'Periapt of Epic Wisdom +10','Wondrous','Epic','No',NULL,'20','1,000,000 gp',NULL,'Craft Wondrous Item, Craft Epic Wondrous Item, commune or legend lore',NULL,'-','\n      <div topic=\"Periapt of Epic Wisdom\" level=\"8\"><p><b>Periapt of Epic Wisdom:</b> This large pearl set on a chain grants an enhancement bonus of +8 or higher to the wearer\'s Wisdom score.</p><p><i>Caster Level:</i> 20th; <i>Prerequisites:</i> Craft Wondrous Item, Craft Epic Wondrous Item, <i>commune</i> or <i>legend lore; Market Price:</i> 640,000 gp (+8), 1,000,000 gp (+10), 1,440,000 gp (+12); <i>Weight:</i> -.</p><p/>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (156,'Periapt of Epic Wisdom +12','Wondrous','Epic','No',NULL,'20','1,440,000 gp',NULL,'Craft Wondrous Item, Craft Epic Wondrous Item, commune or legend lore',NULL,'-','\n      <div topic=\"Periapt of Epic Wisdom\" level=\"8\"><p><b>Periapt of Epic Wisdom:</b> This large pearl set on a chain grants an enhancement bonus of +8 or higher to the wearer\'s Wisdom score.</p><p><i>Caster Level:</i> 20th; <i>Prerequisites:</i> Craft Wondrous Item, Craft Epic Wondrous Item, <i>commune</i> or <i>legend lore; Market Price:</i> 640,000 gp (+8), 1,000,000 gp (+10), 1,440,000 gp (+12); <i>Weight:</i> -.</p><p/>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (157,'Axe of the Dwarvish Lords','Artifact','Major Artifact','No',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Axe of the Dwarvish Lords\" level=\"8\"><p><b>Axe of the Dwarvish Lords:</b> This is a +<i>6 keen throwing goblinoid bane dwarven waraxe</i>. Any dwarf who holds it doubles the range of his or her darkvision. Any nondwarf who grasps the <i>Axe</i> takes 2 points of temporary Charisma damage; these points cannot be healed or restored in any way while the <i>Axe</i> is held. The current owner of the <i>Axe</i> gains a +10 bonus on Craft (armorsmithing, blacksmithing, gemcutting, stonemasonry, and weaponsmithing) checks. The wielder of the <i>Axe</i> can summon an elder earth elemental (as <i>summon monster IX</i>; duration 20 rounds) once per week.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (158,'Codex of the Infinite Planes','Artifact','Major Artifact','No',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Codex of the Infinite Planes\" level=\"8\"><p><b>Codex of the Infinite Planes:</b> The <i>Codex</i> is enormous-supposedly, it requires two strong men to lift it. No matter how many pages are turned, another always remains. Anyone opening the <i>Codex</i> for the first time is utterly annihilated, as with a <i>destruction</i> spell (Fortitude DC 30 for only 10d6 damage). Those who survive can peruse its pages and learn its powers, though not without risk. Each day spent studying the <i>Codex</i> allows the reader to make a Spellcraft check (DC 50) to learn one of its powers (choose the power learned randomly; add a +1 circumstance bonus on the check per additional day spent reading until a power is learned). However, each day of study also forces the reader to make a Will save (DC 30 + 1 per day of study) to avoid being driven insane (as the <i>insanity</i> spell). The powers of the <i>Codex of the Infinite Planes</i> are as follows: <i>astral projection</i>,  <i>banishment</i>,  <i>elemental swarm</i>,  <i>gate</i>,  <i>greater planar ally</i>,  <i>greater planar binding</i>,  <i>plane shift</i>,  and <i>soul bind</i>. Each is usable at will by the owner of the <i>Codex</i> (assuming that he or she has learned how to access the power). The <i>Codex of the Infinite Planes</i> has a caster level of 30th for the purposes of all powers and catastrophes, and all saving throw DCs are 20 + spell level. Activating any power requires both a Concentration check and a Spellcraft check (DC 40 + twice the spell level of the power; the character can\'t take 10 on this check). Any failure on either check indicates a catastrophe befalls the user (roll on the table below for the effect). A character can only incur one catastrophe per power use, even if he or she fails both checks.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>d%</b><br/></td> <td><b>Catastrophe</b> <br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>01-25<br/></td>\n<td>Natural Fury: An <i>earthquake</i> spell centered on the reader strikes every round for 1 minute, and an intensified <i>storm of vengeance</i> spell is centered and targeted on the reader.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>26-50<br/></td>\n<td>Fiendish Vengeance: A <i>Gate</i> opens and 1d3+1 balor demons, pit fiends, or similar evil outsiders immediately step through and attempt to destroy the owner of the <i>Codex</i>. <br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>51-75<br/></td>\n<td>Ultimate Imprisonment: Reader\'s soul is captured (as <i>trap the soul</i>; no save allowed) in a random gem somewhere on the plane while his or her body is entombed beneath the earth (as <i>imprisonment</i>).<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>76-100<br/></td>\n<td>Death: The reader utters a <i>wail of the banshee</i> and then is subject to a <i>destruction</i> spell. This repeats every round for 10 rounds until the reader is dead.<br/></td>\n\n</tr>\n</table>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (159,'Cup and Talisman of the Demigod','Artifact','Major Artifact','No',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Cup and Talisman of the Demigod\" level=\"8\"><p><b>Cup and Talisman of the Demigod:</b> The <i>Cup</i> is a large gem-set golden chalice requiring two hands to lift. It emits light (as the <i>daylight</i> spell) at all times and automatically dispels any darkness-based spells whose area it enters. If the cup is filled with holy water (requiring a full gallon), that substance will act as a <i>potion of cure critical wounds</i> or a <i>potion of neutralize poison</i> (owner\'s choice) if drunk. This liquid can\'t be saved or stored in any way. The <i>Talisman</i> is a small eight-pointed platinum star hanging from a chain of gold and pearls. The wearer gains a +6 enhancement bonus to Charisma and may cast <i>remove blindness/deafness</i>,  <i>remove curse</i>,  and <i>remove disease</i> at will. Furthermore, if the <i>Talisman</i> is placed within the <i>Cup</i> and the <i>Cup</i> filled with holy water, that liquid acts as a special elixir of <i>resurrection</i> (as the spell). This effect will function only once per month. Any evil or chaotic creature that touches the <i>Cup</i> or <i>Talisman</i> is struck with a <i>holy word</i> (if evil) or <i>dictum</i> (if chaotic) spell (or both if the creature is chaotic evil).</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (160,'Eye of the Orc','Artifact','Major Artifact','No',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Eye of the Orc\" level=\"8\"><p><b>Eye of the Orc:</b> This lump of rock has a marquis-cut black sapphire set in its center, making it appear similar to a large eye. If possessed by an orc, it grants a +6 enhancement bonus to Strength and Charisma, and the orc\'s darkvision range is doubled. Nonorcs who possess the <i>Eye</i> gain a +2 enhancement bonus to Strength but take a -2 penalty to Intelligence and Charisma. Regardless of the owner\'s race, any weapon wielded by the owner of the <i>Eye</i> is considered an <i>elf bane weapon</i>. Furthermore, by holding the <i>Eye</i> before the character, he or she can perceive things as if he or she had <i>True seeing</i> cast upon him or her. This can be activated only once per day but lasts as long as the character concentrates on it (requiring a standard action each round).</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (161,'Golem Armor','Artifact','Major Artifact','No',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Golem Armor\" level=\"8\"><p><b>Golem Armor:</b> This enormous suit of black iron +<i>10 full plate armor</i> increases the wearer\'s size by one category (to a maximum of Colossal). The wearer gains a +10 enhancement bonus to Strength and is rendered immune to mind-affecting effects, poison, disease, and similar effects. He or she is not subject to critical hits, subdual damage, ability damage, energy drain, or death from massive damage. <i>Golem Armor</i> is immune to rust attacks. The wearer of <i>Golem Armor</i> gains damage reduction 15/adamantine. He or she also cannot regain hit points by any means (mundane or magical) while the armor is worn. It requires 1 hour to don or extract oneself from <i>Golem Armor</i>.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (162,'Invulnerable Coat','Artifact','Major Artifact','No',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Invulnerable Coat\" level=\"8\"><p><b>Invulnerable Coat:</b> The <i>Invulnerable Coat</i> +<i>5 chain shirt of heavy fortification</i>. It grants its wearer damage reduction 10/epic and resistance 20 against acid, cold, electricity, fire, and sonic energy. If the wearer can turn undead, treat the wearer as having +4 class levels for purposes of caster level, turning undead, smiting evil, and laying on hands.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (163,'Iron Gauntlet of War','Artifact','Major Artifact','No',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Iron Gauntlet of War\" level=\"8\"><p><b>Iron Gauntlet of War:</b> The <i>Gauntlet</i> grants a +8 enhancement bonus to Strength. The wearer doubles the damage bonus on any smite attacks he or she makes. If the wearer has the Leadership feat, the wearer\'s Leadership score increases by +4, but the wearer can never attract or keep followers or cohorts who are good or chaotic. Once per day, the wielder can use <i>implosion</i> as a 20th-level caster (DC 23). The <i>Iron Gauntlet of War</i> is intelligent (Int 13, Wis 18, Cha 24, Ego 26) and lawful evil. It can communicate telepathically with its wearer, though it cannot speak. It will always seek to dominate any wearer who isn\'t lawful evil, forcing such an owner to commit lawful evil deeds (or else find a more suitable wearer).</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (164,'Ring of Nine Facets','Artifact','Major Artifact','No',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Ring of Nine Facets\" level=\"8\"><p><b>Ring of Nine Facets:</b> This ring is set with a gem of nine facets, each one in-scribed with a different incomprehensible rune. Each day at sunrise, the gem turns to display a different facet. The active facet determines the <i>Ring</i>\'s power for that day. Each day, roll 1d10 to determine which facet (and thus which power) is active.</p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>1d10</b><br/></td>\n<td><b>Active Facet Power</b> <br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1<br/></td>\n<td>Wearer is immune to disease<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>2<br/></td>\n<td>Wearer needs no air to survive<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>3<br/></td>\n<td>Wearer gains +5 natural armor bonus<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>4<br/></td>\n<td>Wearer gains low-light vision<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>5<br/></td>\n<td>Wearer gains fast healing 1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>6<br/></td>\n<td>Wearer can <i>fly</i> at will<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>7<br/></td>\n<td>Wearer gains cold resistance 30<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>8<br/></td>\n<td>Wearer gains <i>freedom of movement</i> <br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>9<br/></td>\n<td>Wearer gains +5 resistance bonus on saving throws<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>10<br/></td>\n<td>Wearer may select which facet is active<br/></td>\n\n</tr>\n</table><p/><p>The wearer of the <i>Ring</i> can, with a great deal of mental exertion, attempt to change the active facet away from one he or she does not desire. This requires a full-round action and a Concentration check (DC 50), and deals 2d6 points of nonlethal damage regardless of success. If the save is successful, the new facet is determined randomly. If the <i>Ring</i> is removed, the former wearer takes 2d6 points of nonlethal damage each minute until it is replaced or until his or her nonlethal damage exceeds his or her current hit points (though the nonlethal damage resumes again immediately when the former wearer regains consciousness).</p><p/>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
INSERT INTO item VALUES (165,'Acid Resistance','Armor, Shield',NULL,'Yes','Faint abjuration','3','+18,000 gp',NULL,'Craft Magic Arms and Armor, resist energy',NULL,NULL,'\n      <div topic=\"Acid Resistance\" level=\"8\"><p><b>Acid Resistance:</b> A suit of armor or a shield with this property normally has a dull gray appearance. The armor absorbs the first 10 points of acid damage per attack that the wearer would normally take (similar to the <i>resist energy</i> spell).</p><p>Faint abjuration; CL 3rd; Craft Magic Arms and Armor, <i>resist energy</i>; Price +18,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (166,'Acid Resistance, Improved','Armor, Shield',NULL,'Yes','Moderate abjuration','7','+42,000 gp',NULL,'Craft Magic Arms and Armor, resist energy',NULL,NULL,'\n      <div topic=\"Acid Resistance, Improved\" level=\"8\"><p><b>Acid Resistance, Improved:</b> As acid resistance, except it absorbs the first 20 points of acid damage per attack.</p><p>Moderate abjuration; CL 7th; Craft Magic Arms and Armor, <i>resist energy</i>; Price +42,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (167,'Acid Resistance, Greater','Armor, Shield',NULL,'Yes','Moderate abjuration','11','+66,000 gp',NULL,'Craft Magic Arms and Armor, resist energy',NULL,NULL,'\n      <div topic=\"Acid Resistance, Greater\" level=\"8\"><p><b>Acid Resistance, Greater:</b> As acid resistance, except it absorbs the first 30 points of acid damage per attack.</p><p>Moderate abjuration; CL 11th; Craft Magic Arms and Armor, <i>resist energy</i>; Price +66,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (168,'Animated','Shield',NULL,'Yes','Strong transmutation','12','+2 bonus',NULL,'Craft Magic Arms and Armor, animate objects',NULL,NULL,'\n      <div topic=\"Animated\" level=\"8\"><p><b>Animated:</b> Upon command, an animated shield floats within 2 feet of the wielder, protecting her as if she were using it herself but freeing up both her hands. Only one shield can protect a character at a time. A character with an animated shield still takes any penalties associated with shield use, such as armor check penalty, arcane spell failure chance, and nonproficiency.</p><p>Strong transmutation; CL 12th; Craft Magic Arms and Armor, <i>animate objects</i>; Price +2 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (169,'Arrow Catching','Shield',NULL,'Yes','Moderate abjuration','8','+1 bonus',NULL,'Craft Magic Arms and Armor, entropic shield',NULL,NULL,'\n      <div topic=\"Arrow Catching\" level=\"8\"><p><b>Arrow Catching:</b> A shield with this ability attracts ranged weapons to it. It has a deflection bonus of +1 against ranged weapons because projectiles and thrown weapons veer toward it. Additionally, any projectile or thrown weapon aimed at a target within 5 feet of the shield\'s wearer diverts from its original target and targets the shield\'s bearer instead. (If the wielder has total cover relative to the attacker, the projectile or thrown weapon is not diverted.) Additionally, those attacking the wearer with ranged weapons ignore any miss chances that would normally apply. Projectiles and thrown weapons that have an enhancement bonus higher than the shield\'s base AC bonus are not diverted to the wearer (but the shield\'s increased AC bonus still applies against these weapons). The wielder can activate or deactivate this ability with a command word.</p><p>Moderate abjuration; CL 8th; Craft Magic Arms and Armor, <i>entropic shield</i>; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (170,'Arrow Deflection','Shield',NULL,'Yes','Faint abjuration','5','+2 bonus',NULL,'Craft Magic Arms and Armor, shield',NULL,NULL,'\n      <div topic=\"Arrow Deflection\" level=\"8\"><p><b>Arrow Deflection:</b> This shield protects the wielder as if he had the Deflect Arrows feat. Once per round when he would normally be struck by a ranged weapon, he can make a DC 20 Reflex save. If the ranged weapon has an enhancement bonus, the DC increases by that amount. If he succeeds, the shield deflects the weapon. He must be aware of the attack and not flat-footed. Attempting to deflect a ranged weapon doesn\'t count as an action. Exceptional ranged weapons, such as boulders hurled by giants or <i>acid arrows</i>, can\'t be deflected.</p><p>Faint abjuration; CL 5th; Craft Magic Arms and Armor, <i>shield</i>; Price +2 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (171,'Bashing','Shield',NULL,'Yes','Moderate transmutation','8','+1 bonus',NULL,'Craft Magic Arms and Armor, bull\'s strength',NULL,NULL,'\n      <div topic=\"Bashing\" level=\"8\"><p><b>Bashing:</b> A shield with this special ability is designed to perform a shield bash. A bashing shield deals damage as if it were a weapon of two size categories larger (a Medium light shield thus deals 1d6 points of damage and a Medium heavy shield deals 1d8 points of damage). The shield acts as a +1 weapon when used to bash. (Only light and heavy shields can have this ability.)</p><p>Moderate transmutation; CL 8th; Craft Magic Arms and Armor, <i>bull\'s strength</i>; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (172,'Blinding','Shield',NULL,'Yes','Moderate evocation','7','+1 bonus',NULL,'Craft Magic Arms and Armor, searing light',NULL,NULL,'\n      <div topic=\"Blinding\" level=\"8\"><p><b>Blinding:</b> A shield with this ability flashes with a brilliant light up to twice per day upon command of the wielder. Anyone within 20 feet except the wielder must make a DC 14 Reflex save or be blinded for 1d4 rounds.</p><p>Moderate evocation; CL 7th; Craft Magic Arms and Armor, <i>searing light</i>; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (173,'Cold Resistance','Armor, Shield',NULL,'Yes','Faint abjuration','3','+18,000 gp',NULL,'Craft Magic Arms and Armor, resist energy',NULL,NULL,'\n      <div topic=\"Cold Resistance\" level=\"8\"><p><b>Cold Resistance:</b> A suit of armor or a shield with this property normally has a bluish, icy hue or is adorned with furs and shaggy pelts. The armor absorbs the first 10 points of cold damage per attack that the wearer would normally take (similar to the <i>resist energy</i> spell).</p><p>Faint abjuration; CL 3rd; Craft Magic Arms and Armor, <i>resist energy</i>; Price +18,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (174,'Cold Resistance, Improved','Armor, Shield',NULL,'Yes','Moderate abjuration','7','+42,000 gp',NULL,'Craft Magic Arms and Armor, resist energy',NULL,NULL,'\n      <div topic=\"Cold Resistance, Improved\" level=\"8\"><p><b>Cold Resistance, Improved:</b> As cold resistance, except it absorbs the first 20 points of cold damage per attack.</p><p>Moderate abjuration; CL 7th; Craft Magic Arms and Armor, <i>resist energy</i>; Price +42,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (175,'Cold Resistance, Greater','Armor, Shield',NULL,'Yes','Moderate abjuration','11','+66,000 gp',NULL,'Craft Magic Arms and Armor, resist energy',NULL,NULL,'\n      <div topic=\"Cold Resistance, Greater\" level=\"8\"><p><b>Cold Resistance, Greater:</b> As cold resistance, except it absorbs the first 30 points of cold damage per attack.</p><p>Moderate abjuration; CL 11th; Craft Magic Arms and Armor, <i>resist energy</i>; Price +66,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (176,'Electricity Resistance','Armor, Shield',NULL,'Yes','Faint abjuration','3','+18,000 gp',NULL,'Craft Magic Arms and Armor, resist energy',NULL,NULL,'\n      <div topic=\"Electricity Resistance\" level=\"8\"><p><b>Electricity Resistance:</b> A suit of armor or a shield with this property normally has a bluish hue and often bears a storm or lightning motif. The armor absorbs the first 10 points of electricity damage per attack that the wearer would normally take (similar to the <i>resist energy</i> spell).</p><p>Faint abjuration; CL 3rd; Craft Magic Arms and Armor, <i>resist energy</i>; Price +18,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (177,'Electricity Resistance, Improved','Armor, Shield',NULL,'Yes','Moderate abjuration','7','+42,000 gp',NULL,'Craft Magic Arms and Armor, resist energy',NULL,NULL,'\n      <div topic=\"Electricity Resistance, Improved\" level=\"8\"><p><b>Electricity Resistance, Improved:</b> As electricity resistance, except it absorbs the first 20 points of electricity damage per attack.</p><p>Moderate abjuration; CL 7th; Craft Magic Arms and Armor, <i>resist energy</i>; Price +42,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (178,'Electricity Resistance, Greater','Armor, Shield',NULL,'Yes','Moderate abjuration','11','+66,000 gp',NULL,'Craft Magic Arms and Armor, resist energy',NULL,NULL,'\n      <div topic=\"Electricity Resistance, Greater\" level=\"8\"><p><b>Electricity Resistance, Greater:</b> As electricity resistance, except it absorbs the first 30 points of electricity damage per attack.</p><p>Moderate abjuration; CL 11th; Craft Magic Arms and Armor, <i>resist energy</i>; Price +66,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (179,'Etherealness','Armor',NULL,'Yes','Strong transmutation','13','+49,000 gp',NULL,'Craft Magic Arms and Armor, ethereal jaunt',NULL,NULL,'\n      <div topic=\"Etherealness\" level=\"8\"><p><b>Etherealness:</b> On command, this ability allows the wearer of the armor to become ethereal (as the <i>ethereal jaunt</i> spell) once per day. The character can remain ethereal for as long as desired, but once he returns to normal, he cannot become ethereal again that day.</p><p>Strong transmutation; CL 13th; Craft Magic Arms and Armor, <i>ethereal jaunt</i>; Price +49,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (180,'Fire Resistance','Armor',NULL,'Yes','Faint abjuration','3','+18,000 gp',NULL,'Craft Magic Arms and Armor, resist energy',NULL,NULL,'\n      <div topic=\"Fire Resistance\" level=\"8\"><p><b>Fire Resistance:</b> A suit of armor with this ability normally has a reddish hue and often is decorated with a draconic motif. The armor absorbs the first 10 points of fire damage per attack that the wearer would normally take (similar to the <i>resist energy</i> spell).</p><p>Faint abjuration; CL 3rd; Craft Magic Arms and Armor, <i>resist energy</i>; Price +18,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (181,'Fire Resistance, Improved','Armor, Shield',NULL,'Yes','Moderate abjuration','7','+42,000 gp',NULL,'Craft Magic Arms and Armor, resist energy',NULL,NULL,'\n      <div topic=\"Fire Resistance, Improved\" level=\"8\"><p><b>Fire Resistance, Improved:</b> As fire resistance, except it absorbs the first 20 points of fire damage per attack.</p><p>Moderate abjuration; CL 7th; Craft Magic Arms and Armor, <i>resist energy</i>; Price +42,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (182,'Fire Resistance, Greater','Armor, Shield',NULL,'Yes','Moderate abjuration','11','+66,000 gp',NULL,'Craft Magic Arms and Armor, resist energy',NULL,NULL,'\n      <div topic=\"Fire Resistance, Greater\" level=\"8\"><p><b>Fire Resistance, Greater:</b> As fire resistance, except it absorbs the first 30 points of fire damage per attack.</p><p>Moderate abjuration; CL 11th; Craft Magic Arms and Armor, <i>resist energy</i>; Price +66,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (183,'Fortification','Armor, Shield',NULL,'Yes','Strong abjuration','13','varies (see above)',NULL,'Craft Magic Arms and Armor, limited wish or miracle',NULL,NULL,'\n      <div topic=\"Fortification\" level=\"8\"><p><b>Fortification:</b> This suit of armor or shield produces a magical force that protects vital areas of the wearer more effectively. When a critical hit or sneak attack is scored on the wearer, there is a chance that the critical hit or sneak attack is negated and damage is instead rolled normally.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td><b>Fortification Type</b><br/></td> <td><b>Chance for Normal Damage</b><br/></td>\n<td><b>Base Price Modifier</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Light<br/></td>\n<td>25%<br/></td>\n<td>+1 bonus<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Moderate<br/></td>\n<td>75%<br/></td>\n<td>+3 bonus<br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Heavy<br/></td>\n<td>100%<br/></td>\n<td>+5 bonus<br/></td>\n\n</tr>\n</table><p>Strong abjuration; CL 13th; Craft Magic Arms and Armor, <i>limited wish</i> or <i>miracle</i>; Price varies (see above).</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (184,'Ghost Touch','Armor, Shield',NULL,'Yes','Strong transmutation','15','+3 bonus',NULL,'Craft Magic Arms and Armor, etherealness',NULL,NULL,'\n      <div topic=\"Ghost Touch\" level=\"8\"><p><b>Ghost Touch:</b> This armor or shield seems almost translucent. Both its enhancement bonus and its armor bonus count against the attacks of incorporeal creatures. It can be picked up, moved, and worn by incorporeal creatures at any time. Incorporeal creatures gain the armor or shield\'s enhancement bonus against both corporeal and incorporeal attacks, and they can still pass freely through solid objects.</p><p>Strong transmutation; CL 15th; Craft Magic Arms and Armor, <i>etherealness</i>; Price +3 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (185,'Glamered','Armor',NULL,'Yes','Moderate illusion','10','+2,700 gp',NULL,'Craft Magic Arms and Armor, disguise self',NULL,NULL,'\n      <div topic=\"Glamered\" level=\"8\"><p><b>Glamered:</b> A suit of armor with this ability appears normal. Upon command, the armor changes shape and form to assume the appearance of a normal set of clothing. The armor retains all its properties (including weight) when glamered. Only a <i>true seeing</i> spell or similar magic reveals the true nature of the armor when disguised.</p><p>Moderate illusion; CL 10th; Craft Magic Arms and Armor, <i>disguise self</i>; Price +2,700 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (186,'Invulnerability','Armor',NULL,'Yes','Strong abjuration and perhaps evocation (if miracle is used)','18','+3 bonus',NULL,'Craft Magic Arms and Armor, stoneskin, wish or miracle',NULL,NULL,'\n      <div topic=\"Invulnerability\" level=\"8\"><p><b>Invulnerability:</b> This suit of armor grants the wearer damage reduction of 5/magic.</p><p>Strong abjuration and perhaps evocation (if <i>miracle</i> is used); CL 18th; Craft Magic Arms and Armor, <i>stoneskin</i>,  <i>wish</i> or <i>miracle</i>; Price +3 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (187,'Reflecting','Shield',NULL,'Yes','Strong abjuration','14','+5 bonus',NULL,'Craft Magic Arms and Armor, spell turning',NULL,NULL,'\n      <div topic=\"Reflecting\" level=\"8\"><p><b>Reflecting:</b> This shield seems like a mirror. Its surface is completely reflective. Once per day, it can be called on to reflect a spell back at its caster exactly like the <i>spell turning</i> spell.</p><p>Strong abjuration; CL 14th; Craft Magic Arms and Armor, <i>spell turning</i>; Price +5 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (188,'Shadow','Armor',NULL,'Yes','Faint illusion','5','+3,750 gp',NULL,'Craft Magic Arms and Armor, invisibility',NULL,NULL,'\n      <div topic=\"Shadow\" level=\"8\"><p><b>Shadow:</b> This armor is jet black and blurs the wearer whenever she tries to hide, granting a +5 competence bonus on Hide checks. (The armor\'s armor check penalty still applies normally.)</p><p>Faint illusion; CL 5th; Craft Magic Arms and Armor, <i>invisibility</i>; Price +3,750 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (189,'Shadow, Improved','Armor, Shield',NULL,'Yes','Moderate illusion','10','+15,000 gp',NULL,'Craft Magic Arms and Armor, invisibility',NULL,NULL,'\n      <div topic=\"Shadow, Improved\" level=\"8\"><p><b>Shadow, Improved:</b> As shadow, except it grants a +10 competence bonus on Hide checks.</p><p>Moderate illusion; CL 10th; Craft Magic Arms and Armor, <i>invisibility</i>; Price +15,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (190,'Shadow, Greater','Armor, Shield',NULL,'Yes','Moderate illusion','15','+33,750 gp',NULL,'Craft Magic Arms and Armor, invisibility',NULL,NULL,'\n      <div topic=\"Shadow, Greater\" level=\"8\"><p><b>Shadow, Greater:</b> As shadow, except it grants a +15 competence bonus on Hide checks.</p><p>Moderate illusion; CL 15th; Craft Magic Arms and Armor, <i>invisibility</i>; Price +33,750 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (191,'Silent Moves','Armor',NULL,'Yes','Faint illusion','5','+3,750 gp',NULL,'Craft Magic Arms and Armor, silence',NULL,NULL,'\n      <div topic=\"Silent Moves\" level=\"8\"><p><b>Silent Moves:</b> This armor is well oiled and magically constructed so that it not only makes little sound, but it dampens sound around it. It provides a +5 competence bonus on its wearer\'s Move Silently checks. (The armor\'s armor check penalty still applies normally.)</p><p>Faint illusion; CL 5th; Craft Magic Arms and Armor, <i>silence</i>; Price +3,750 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (192,'Silent Moves, Improved','Armor, Shield',NULL,'Yes','Moderate illusion','10','+15,000 gp',NULL,'Craft Magic Arms and Armor, silence',NULL,NULL,'\n      <div topic=\"Silent Moves, Improved\" level=\"8\"><p><b>Silent Moves, Improved:</b> As silent moves, except it grants a +10 competence bonus on Move Silently checks.</p><p>Moderate illusion; CL 10th; Craft Magic Arms and Armor, <i>silence</i>; Price +15,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (193,'Silent Moves, Greater','Armor, Shield',NULL,'Yes','Moderate illusion','15','+33,750 gp',NULL,'Craft Magic Arms and Armor, silence',NULL,NULL,'\n      <div topic=\"Silent Moves, Greater\" level=\"8\"><p><b>Silent Moves, Greater:</b> As silent moves, except it grants a +15 competence bonus on Move Silently checks.</p><p>Moderate illusion; CL 15th; Craft Magic Arms and Armor, <i>silence</i>; Price +33,750 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (194,'Slick','Armor',NULL,'Yes','Faint conjuration','4','+3,750 gp',NULL,'Craft Magic Arms and Armor, grease',NULL,NULL,'\n      <div topic=\"Slick\" level=\"8\"><p><b>Slick:</b> Slick armor seems coated at all times with a slightly greasy oil. It provides a +5 competence bonus on its wearer\'s Escape Artist checks. (The armor\'s armor check penalty still applies normally.)</p><p>Faint conjuration; CL 4th; Craft Magic Arms and Armor, <i>grease</i>; Price +3,750 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (195,'Slick, Improved','Armor, Shield',NULL,'Yes','Moderate conjuration','10','+15,000 gp',NULL,'Craft Magic Arms and Armor, grease',NULL,NULL,'\n      <div topic=\"Slick, Improved\" level=\"8\"><p><b>Slick, Improved:</b> As slick, except it grants a +10 competence bonus on Escape Artist checks.</p><p>Moderate conjuration; CL 10th; Craft Magic Arms and Armor, <i>grease</i>; Price +15,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (196,'Slick, Greater','Armor, Shield',NULL,'Yes','Moderate conjuration','15','+33,750 gp',NULL,'Craft Magic Arms and Armor, grease',NULL,NULL,'\n      <div topic=\"Slick, Greater\" level=\"8\"><p><b>Slick, Greater:</b> As slick, except it grants a +15 competence bonus on Escape Artist checks.</p><p>Moderate conjuration; CL 15th; Craft Magic Arms and Armor, <i>grease</i>; Price +33,750 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (197,'Sonic Resistance','Armor, Shield',NULL,'Yes','Faint abjuration','3','+18,000 gp',NULL,'Craft Magic Arms and Armor, resist energy',NULL,NULL,'\n      <div topic=\"Sonic Resistance\" level=\"8\"><p><b>Sonic Resistance:</b> A suit of armor or a shield with this property normally has a glistening appearance. The armor absorbs the first 10 points of sonic damage per attack that the wearer would normally take (similar to the <i>resist energy</i> spell).</p><p>Faint abjuration; CL 3rd; Craft Magic Arms and Armor, <i>resist energy</i>; Price +18,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
